\caption{Per-example overlap (Jaccard) at h3, 1.3B. LAMBADA ref.\ column shows ratio to LAMBADA Jaccard.}\label{tab:jaccard}
\begin{tabular}{@{}lcccc@{}}
\toprule
\textbf{Bench.} & \textbf{$J$(help)} & \textbf{$J$(hurt)} & \textbf{Ref.} & \textbf{Interp.} \\
